import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"记忆","description":"Hearth 如何积累可纠正的背景，同时避免无来源、不可遗忘或自行扩权的记忆。","frontmatter":{"title":"记忆","description":"Hearth 如何积累可纠正的背景，同时避免无来源、不可遗忘或自行扩权的记忆。","outline":false},"headers":[],"relativePath":"design/memory.md","filePath":"design/memory.md","lastUpdated":1795175458000}'),o={name:"design/memory.md"};function h(i,t,n,l,s,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h1><p class="lead">记忆不是聊天记录，也不是越多越好。它是一层受约束的判断缓存，帮助系统减少重复询问；是否写入、何时召回、如何遗忘都由用户看得见的规则控制。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>系统要记住用户反复提供的背景、偏好、项目事实和过去任务的经验。召回记忆时，要能说明它来自哪里、有多可信、适用于哪个范围、是否过期，以及为什么这次被使用。</p><p>记忆必须可纠正、可遗忘。用户可以查看系统记住了什么，修改错误内容，限制敏感信息的用途，并确认删除已经传播到索引、缓存和派生摘要，而不是只删掉原页面。</p><p>记忆不能成为事实源。任务状态、审批、产物和回执来自记录；记忆只提供背景，不能自行创建新凭据、后台任务或更大的授权范围。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>Hearth 把记忆分成四类，分别控制生命周期和用途。</p><table tabindex="0"><thead><tr><th>记忆类型</th><th>保存什么</th><th>生命周期与用途</th></tr></thead><tbody><tr><td>工作记忆</td><td>当前任务约束、临时观察和中间结果</td><td>任务结束清理，只服务当前执行</td></tr><tr><td>经历记忆</td><td>过去任务的经过、结果、失败和人工纠偏</td><td>中期保存，可摘要，用于相似任务参考</td></tr><tr><td>事实记忆</td><td>人物、项目、组织和稳定关系</td><td>长期保存，必须有来源、有效期和敏感度</td></tr><tr><td>用户模型</td><td>偏好、沟通风格、习惯和价值边界</td><td>长期保存，高度可编辑，减少重复说明</td></tr></tbody></table><p>记忆写入先进入候选状态，检查来源、敏感度、重复、冲突和用户授权。网页、邮件、文档和工具输出都可能包含误导内容，不能因为出现一次就自动成为高可信事实；高敏感信息默认不自动写入。</p><p>检索按任务需要、适用范围、来源可信度、时效、敏感度和上下文预算筛选。系统不会把全部记忆塞进一次任务，也不会让不同账户或项目互相污染。新事实不能静默覆盖旧事实，冲突时保留来源并请求确认；低置信度记忆不能单独触发高风险动作。</p><p>遗忘要传播到缓存、语义索引和派生摘要。缓存必须有版本、失效和删除规则，不能把已经遗忘的内容重新召回。</p><h2 id="与资料库的关系" tabindex="-1">与资料库的关系 <a class="header-anchor" href="#与资料库的关系" aria-label="Permalink to &quot;与资料库的关系&quot;">​</a></h2><p>Hearth 是记忆的唯一写权威。记忆会投影到本地资料库的统一文件树，供检索和阅读；投影先按状态（待确认、已记住、有冲突、已替代）分层，再按事实、偏好、项目、承诺、经验和方法分组。删除、遗忘和回收站仍由记忆服务控制，重建检索数据不会改变记忆本身的来源和遗忘状态。完整边界见<a href="/hearth-os/design/knowledge.html">资料库与检索</a>。</p>',14)])])}const _=a(o,[["render",h]]);export{m as __pageData,_ as default};
